  /** Only increase alpha value if paint alpha is higher than existing Default: False. */
  get use_absolute_alpha(): H.Ref<boolean>;
  set use_absolute_alpha(v: H.In<boolean>);
  /** Paint wetness, visible in wetmap (some effects only affect wet paint) Range: 0 to 1. Default: 0.0. */
  get paint_wetness(): H.Ref<number>;
  set paint_wetness(v: H.In<number>);
  /** Erase / remove paint instead of adding it Default: False. */
  get use_paint_erase(): H.Ref<boolean>;
  set use_paint_erase(v: H.In<boolean>);
  /**
   * Wave Type Default: 'DEPTH'.
   * - `CHANGE`: Depth Change
   * - `DEPTH`: Obstacle
   * - `FORCE`: Force
   * - `REFLECT`: Reflect Only
   */
  get wave_type(): H.Ref<"CHANGE" | "DEPTH" | "FORCE" | "REFLECT">;
  set wave_type(v: H.In<"CHANGE" | "DEPTH" | "FORCE" | "REFLECT">);
  /** Multiplier for wave influence of this brush Range: -2 to 2. Default: 0.0. */
  get wave_factor(): H.Ref<number>;
  set wave_factor(v: H.In<number>);
  /** Maximum level of surface intersection used to influence waves (use 0.0 to disable) Range: 0 to 50. Default: 0.0. */
  get wave_clamp(): H.Ref<number>;
  set wave_clamp(v: H.In<number>);
  /** Make this brush to smudge existing paint as it moves Default: False. */
  get use_smudge(): H.Ref<boolean>;
  set use_smudge(v: H.In<boolean>);
  /** Smudge effect strength Range: 0 to 1. Default: 0.0. */
  get smudge_strength(): H.Ref<number>;
  set smudge_strength(v: H.In<number>);
  /** Velocity considered as maximum influence (Blender units per frame) Range: 0.00009999999747378752 to 10. Default: 0.0. */
  get velocity_max(): H.Ref<number>;
  set velocity_max(v: H.In<number>);
  /** Multiply brush influence by velocity color ramp alpha Default: False. */
  get use_velocity_alpha(): H.Ref<boolean>;
  set use_velocity_alpha(v: H.In<boolean>);
  /** Multiply brush intersection depth (displace, waves) by velocity ramp alpha Default: False. */
  get use_velocity_depth(): H.Ref<boolean>;
  set use_velocity_depth(v: H.In<boolean>);
  /** Replace brush color by velocity color ramp Default: False. */
  get use_velocity_color(): H.Ref<boolean>;
  set use_velocity_color(v: H.In<boolean>);
  /**
   * Paint Source Default: 'VOLUME'.
   * - `PARTICLE_SYSTEM`: Particle System
   * - `POINT`: Object Center
   * - `DISTANCE`: Proximity
   * - `VOLUME_DISTANCE`: Mesh Volume + Proximity
   * - `VOLUME`: Mesh Volume
   */
  get paint_source(): H.Ref<"PARTICLE_SYSTEM" | "POINT" | "DISTANCE" | "VOLUME_DISTANCE" | "VOLUME">;
  set paint_source(v: H.In<"PARTICLE_SYSTEM" | "POINT" | "DISTANCE" | "VOLUME_DISTANCE" | "VOLUME">);
  /** Maximum distance from brush to mesh surface to affect paint Range: 0 to 500. Default: 0.0. */
  get paint_distance(): H.Ref<number>;
  set paint_distance(v: H.In<number>);
  /** Only read color ramp alpha Default: False. */
  get use_proximity_ramp_alpha(): H.Ref<boolean>;
  set use_proximity_ramp_alpha(v: H.In<boolean>);
  /**
   * Proximity falloff type Default: 'CONSTANT'.
   * - `SMOOTH`: Smooth
   * - `CONSTANT`: Constant
   * - `RAMP`: Color Ramp
   */
  get proximity_falloff(): H.Ref<"SMOOTH" | "CONSTANT" | "RAMP">;
  set proximity_falloff(v: H.In<"SMOOTH" | "CONSTANT" | "RAMP">);
  /** Brush is projected to canvas from defined direction within brush proximity Default: False. */
  get use_proximity_project(): H.Ref<boolean>;
  set use_proximity_project(v: H.In<boolean>);
  /**
   * Ray direction to use for projection (if brush object is located in that direction it's painted) Default: 'CANVAS'.
   * - `CANVAS`: Canvas Normal
   * - `BRUSH`: Brush Normal
   * - `Z_AXIS`: Z-Axis
   */
  get ray_direction(): H.Ref<"CANVAS" | "BRUSH" | "Z_AXIS">;
  set ray_direction(v: H.In<"CANVAS" | "BRUSH" | "Z_AXIS">);
  /** Proximity falloff is applied inside the volume Default: False. */
  get invert_proximity(): H.Ref<boolean>;
  set invert_proximity(v: H.In<boolean>);
  /** Negate influence inside the volume Default: False. */
  get use_negative_volume(): H.Ref<boolean>;
  set use_negative_volume(v: H.In<boolean>);
  /** The particle system to paint with */
  get particle_system(): H.Ptr<R.ParticleSystem>;
  set particle_system(v: R.ParticleSystem | null);
  /** Use radius from particle settings Default: False. */
  get use_particle_radius(): H.Ref<boolean>;
  set use_particle_radius(v: H.In<boolean>);
  /** Radius that will be painted solid Range: 0.009999999776482582 to 10. Default: 0.0. */
  get solid_radius(): H.Ref<number>;
  set solid_radius(v: H.In<number>);
  /** Smooth falloff added after solid radius Range: 0 to 10. Default: 0.0. */
  get smooth_radius(): H.Ref<number>;
  set smooth_radius(v: H.In<number>);
  /** Color ramp used to define proximity falloff */
  get paint_ramp(): H.Ptr<R.ColorRamp>;
  /** Color ramp used to define brush velocity effect */
